import{c as s,Q as e,j as i,m as o}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"Session Insights — 對稱懷疑原則與計劃書制訂紀律","description":"","frontmatter":{"title":"Session Insights — 對稱懷疑原則與計劃書制訂紀律","date":"2026-06-07T00:00:00.000Z","related":"research/reports/2026-06-07-deep-practices-v2-execution-plan.md","session_topic":"deep-practices-v2 執行計劃書制訂","type":"session-insights"},"headers":[],"relativePath":"research/reports/2026-06-07-session-insights-symmetric-skepticism.md","filePath":"research/reports/2026-06-07-session-insights-symmetric-skepticism.md","lastUpdated":1780842316000}'),r={name:"research/reports/2026-06-07-session-insights-symmetric-skepticism.md"};function n(a,t,l,c,d,h){return e(),i("div",null,[...t[0]||(t[0]=[o('<h1 id="session-insights-—-對稱懷疑原則" tabindex="-1">Session Insights — 對稱懷疑原則 <a class="header-anchor" href="#session-insights-—-對稱懷疑原則" aria-label="Permalink to &quot;Session Insights — 對稱懷疑原則&quot;">​</a></h1><blockquote><p>本 session 從「為研究報告制訂執行計劃書」中萃取的可複用方法論。核心是一條跨任務的判斷紀律：<strong>對外部建議的懷疑必須對稱</strong>。</p></blockquote><hr><h2 id="核心-insight-對稱懷疑-symmetric-skepticism" tabindex="-1">核心 Insight：對稱懷疑（Symmetric Skepticism） <a class="header-anchor" href="#核心-insight-對稱懷疑-symmetric-skepticism" aria-label="Permalink to &quot;核心 Insight：對稱懷疑（Symmetric Skepticism）&quot;">​</a></h2><h3 id="問題" tabindex="-1">問題 <a class="header-anchor" href="#問題" aria-label="Permalink to &quot;問題&quot;">​</a></h3><p>制訂執行計劃書時，最自然的失敗模式是把報告的行動清單<strong>逐條當待辦鋪開</strong>。workspace 既有紀律已能擋住一半——對「幻覺 key」（技術上不存在的建議，如 <code>autoCompactAt</code>/<code>tokenBudget</code>）有警覺。但這個警覺是<strong>不對稱</strong>的：只防「技術不存在」，不防「技術存在但撞既有設計」。</p><h3 id="原則" tabindex="-1">原則 <a class="header-anchor" href="#原則" aria-label="Permalink to &quot;原則&quot;">​</a></h3><blockquote><p>對外部建議的懷疑要對稱地套用到兩個方向：</p><ol><li><strong>技術不存在</strong>（幻覺 key）→ 剔除</li><li><strong>技術有效但撞既有刻意設計</strong>（tradeoff 非 fix）→ 不自動執行，AskUserQuestion 待決</li></ol></blockquote><p>第二類最危險，因為它「看起來是對的」會通過 grep 驗證。本 session 抓到三個：</p><table tabindex="0"><thead><tr><th>建議</th><th>表面</th><th>實際</th></tr></thead><tbody><tr><td>skill body 壓到 250-450 words</td><td>子代理機械判「25/27 超標」</td><td>pilot/hub 多命令 skill 不適用單指令上限；壓縮 = 砍真實操作內容 = 違反「不破壞 working」</td></tr><tr><td>P0-4 釘 subagent model=Sonnet</td><td>「防靜默降級 Haiku」</td><td>破壞 subagent-strategy「0–1檔 Haiku」省錢路由 = tradeoff 非 fix</td></tr><tr><td><code>CLAUDE_AUTOCOMPACT_PCT_OVERRIDE</code></td><td>真實 env（非幻覺）</td><td>MEMORY 標「has bug」→ 真實 ≠ 該用</td></tr></tbody></table><p><strong>判準</strong>：一條建議若與 ADR / 既有刻意設計衝突，它是「決策」不是「修補」→ 交使用者，不靜默選。這與 core.md「浮現矛盾不靜默選擇」同源，但延伸到「外部報告 vs 既有設計」的矛盾。</p><hr><h2 id="insight-2-子代理-verdict-的「詮釋層」誤判" tabindex="-1">Insight 2：子代理 verdict 的「詮釋層」誤判 <a class="header-anchor" href="#insight-2-子代理-verdict-的「詮釋層」誤判" aria-label="Permalink to &quot;Insight 2：子代理 verdict 的「詮釋層」誤判&quot;">​</a></h2><p><code>unverified_success</code> 閘門過去聚焦「數字是否屬實」。本 session 揭露更隱蔽的一層：<strong>數字屬實但詮釋錯</strong>。</p><ul><li>skill 字數 25/27 超標：grep 屬實，但「超標 → 該壓縮」的詮釋錯（忽略 pilot/hub 是多命令 skill）。</li><li><code>memory-sync.sh:44 exit 1</code>：子代理判「誤用應改 exit 0」，但親讀上下文發現是「sync 失敗不阻斷 session」的正確語義（exit 2 才 block）。</li></ul><p><strong>教訓</strong>：機械 grep 重驗能抓「數字幻覺」，抓不到「詮釋幻覺」。詮釋幻覺需主對話<strong>親讀上下文 + 領域知識</strong>判斷，不能只驗數字成員資格。→ 親驗範圍應含「該數字的詮釋是否成立」，非只「該數字是否存在」。</p><hr><h2 id="insight-3-「試跑」前先驗功能的執行模型" tabindex="-1">Insight 3：「試跑」前先驗功能的執行模型 <a class="header-anchor" href="#insight-3-「試跑」前先驗功能的執行模型" aria-label="Permalink to &quot;Insight 3：「試跑」前先驗功能的執行模型&quot;">​</a></h2><p>Q2 要求「試跑 Agent Teams 評估」。對稱懷疑先驗 flag 真偽（確認 <code>CLAUDE_CODE_EXPERIMENTAL_AGENT_TEAMS</code> 是真實 flag，非幻覺）——但官方文件揭露更關鍵的<strong>執行模型約束</strong>：</p><blockquote><p>Agent Teams 是互動式 CLI session 級編排（lead spawn teammates via tmux/pane）。官方明載「No nested teams：teammates cannot spawn their own teams」。當前 runtime 是被 spawn 的 agent → <strong>無法在此 session 內程式化試跑</strong>。</p></blockquote><p><strong>教訓</strong>：「試跑某功能」前，除了驗功能存在，還要驗<strong>該功能的執行模型是否相容當前執行環境</strong>。不相容時誠實回報邊界（交付啟用指南），不假裝跑了（unverified_success 紀律的延伸：不只「未驗證的成功」，還有「環境不允許的執行」）。</p><hr><h2 id="可複用-checklist-制訂執行計劃書時" tabindex="-1">可複用 Checklist：制訂執行計劃書時 <a class="header-anchor" href="#可複用-checklist-制訂執行計劃書時" aria-label="Permalink to &quot;可複用 Checklist：制訂執行計劃書時&quot;">​</a></h2><ol><li><strong>對稱懷疑每條建議</strong>：① 技術存在？②（存在則）撞既有設計嗎？→ 撞 = tradeoff 交使用者</li><li><strong>親驗子代理 verdict 的兩層</strong>：數字屬實？詮釋成立？（後者需親讀上下文）</li><li><strong>「試跑/執行」前驗執行模型相容性</strong>：功能存在 ≠ 當前環境可執行</li><li><strong>誠實 gap 為主軸</strong>：前置「多數已做/無效」事實，不把報告清單逐條當待辦（反湊數紀律）</li><li><strong>被剔除清單也要記錄</strong>：剔除理由寫進計劃書，避免下次重複評估</li></ol><hr><h2 id="與既有紀律的關係" tabindex="-1">與既有紀律的關係 <a class="header-anchor" href="#與既有紀律的關係" aria-label="Permalink to &quot;與既有紀律的關係&quot;">​</a></h2><ul><li><strong>延伸</strong> core.md「浮現矛盾不靜默選擇」→ 外部報告 vs 既有設計的矛盾</li><li><strong>延伸</strong> subagent-strategy「verdict 非證據必 grep 重驗」→ 加「詮釋層」親驗</li><li><strong>延伸</strong> core.md <code>unverified_success</code> 閘門 → 加「環境不允許的執行」維度</li><li><strong>呼應</strong> Lesson 2026-06-07-C（幻覺 key）→ 對稱化為「真實但撞設計」也須擋</li></ul>',27)])])}const m=s(r,[["render",n]]);export{p as __pageData,m as default};
